def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rows = intervals(h, sep_rows)
    cols = intervals(w, sep_cols)
    out = [row[:] for row in grid]

    # Each 2x2 tile motif consists of one pattern and its horizontal,
    # vertical, and combined reflections.
    for tr in range(len(rows) - 1):
        r0, r1 = rows[tr]
        r2, r3 = rows[tr + 1]
        if r1 - r0 != r3 - r2:
            continue
        th = r1 - r0

        for tc in range(len(cols) - 1):
            c0, c1 = cols[tc]
            c2, c3 = cols[tc + 1]
            if c1 - c0 != c3 - c2:
                continue
            tw = c1 - c0

            for color in range(1, 10):
                tiles = [
                    [(r, c) for r in range(ra, rb) for c in range(ca, cb)
                     if grid[r][c] == color]
                    for ra, rb, ca, cb in (
                        (r0, r1, c0, c1), (r0, r1, c2, c3),
                        (r2, r3, c0, c1), (r2, r3, c2, c3)
                    )
                ]
                occupied = [i for i, cells in enumerate(tiles) if cells]
                if len(occupied) < 3:
                    continue

                canonical = []
                for i in occupied:
                    flip_v = i // 2
                    flip_h = i % 2
                    ra, rb = (r0, r1) if i < 2 else (r2, r3)
                    ca, cb = (c0, c1) if i % 2 == 0 else (c2, c3)
                    pattern = set()
                    for r, c in tiles[i]:
                        rr = r - ra
                        cc = c - ca
                        if flip_v:
                            rr = th - 1 - rr
                        if flip_h:
                            cc = tw - 1 - cc
                        pattern.add((rr, cc))
                    canonical.append(pattern)

                if not all(p == canonical[0] for p in canonical[1:]):
                    continue

                pattern = canonical[0]
                bounds = ((r0, r1, c0, c1), (r0, r1, c2, c3),
                          (r2, r3, c0, c1), (r2, r3, c2, c3))
                for i, (ra, rb, ca, cb) in enumerate(bounds):
                    if i in occupied:
                        continue
                    for rr, cc in pattern:
                        if i // 2:
                            rr = th - 1 - rr
                        if i % 2:
                            cc = tw - 1 - cc
                        out[ra + rr][ca + cc] = color

    return out
